  1	/**
  2	 * Typed messages between units (and from the operator), stored in the operation record.
  3	 *
  4	 * Concurrency forbids shared mutable memory: a unit may not read another unit's in-flight workspace, and a summary
  5	 * is not accessible just because it exists. Everything that crosses a unit boundary does so as a persisted message
  6	 * with a sender, a recipient, a kind and a delivery record. A message is advisory context, never verification
  7	 * evidence: it cannot change a TurnResult, satisfy a verifier, or substitute for an independence check.
  8	 *
  9	 * Delivery is at most once. The runner marks a message delivered in the same save that records the unit's RUNNING
 10	 * transition, so a crash either delivers it with the transition or not at all.
 11	 */
 12	import type { DurableOperationState, OperationMessage, OperationMessageKind } from "./operation.js";
 13	
 14	/** Messages retained per operation. Old delivered messages are dropped first; the record stays bounded. */
 15	export const MAX_MESSAGES = 200;
 16	/** Messages delivered to one turn. A unit's start prompt must stay small and predictable. */
 17	export const MAX_MESSAGES_PER_TURN = 20;
 18	/** A message body is short by design: it carries a summary and pointers, not content. */
 19	export const MAX_MESSAGE_BODY = 4_000;
 20	
 21	const KINDS: ReadonlySet<string> = new Set(["request", "observation", "artifact", "verdict"]);
 22	const REF_KINDS: ReadonlySet<string> = new Set(["file", "receipt", "unit", "checkpoint"]);
 23	// C0 (except TAB/LF), CR, DEL, C1: rejected at write time rather than stripped, so the sender learns the body was
 24	// unsafe instead of silently handing the recipient something different from what it sent. CR is rejected because a
 25	// message body is rendered line-oriented in a prompt and in a terminal.
 26	const UNSAFE = /[\u0000-\u0008\u000b\u000c\u000d\u000e-\u001f\u007f-\u009f]/;
 27	
 28	/** A message the operation will not store. */
 29	export class MessageRejected extends Error {}
 30	
 31	export interface MessageInput {
 32	  from: string;
 33	  /** A unit id, or `*` for the operation. */
 34	  to: string;
 35	  kind: OperationMessageKind;
 36	  body: string;
 37	  refs?: OperationMessage["refs"];
 38	}
 39	
 40	export interface PublishResult {
 41	  message: OperationMessage;
 42	  /** Messages dropped to stay within `MAX_MESSAGES`; the caller reports them as an event. */
 43	  dropped: OperationMessage[];
 44	}
 45	
 46	/**
 47	 * The next id. It comes from a durable counter, not from the surviving messages: a pruned message's id is cited by
 48	 * `OPERATION_MESSAGE` events, so reusing it would make two different messages share an id in the timeline.
 49	 */
 50	function nextId(state: DurableOperationState): string {
 51	  let highest = state.messageSeq ?? 0;
 52	  for (const message of state.messages ?? []) {
 53	    const match = /^msg-(\d+)$/.exec(message.id);
 54	    if (match) highest = Math.max(highest, Number(match[1]));
 55	  }
 56	  const next = highest + 1;
 57	  state.messageSeq = next;
 58	  return `msg-${next}`;
 59	}
 60	
 61	/**
 62	 * Validates and appends one message. `to` must name a unit of this operation or be `*`; a body must be non-empty,
 63	 * within bounds and free of control characters. The caller persists the state.
 64	 */
 65	export function publishMessage(state: DurableOperationState, input: MessageInput, now: number): PublishResult {
 66	  const from = input.from.trim();
 67	  const to = input.to.trim();
 68	  if (!from) throw new MessageRejected("a message needs a sender");
 69	  if (!to) throw new MessageRejected("a message needs a recipient ('*' for the whole operation)");
 70	  if (to !== "*" && !state.units.some((unit) => unit.id === to)) {
 71	    throw new MessageRejected(`no work unit '${to}' in this operation (recipients: ${state.units.map((u) => u.id).join(", ")})`);
 72	  }
 73	  if (!KINDS.has(input.kind)) throw new MessageRejected(`unknown message kind '${String(input.kind)}' (known: ${[...KINDS].join(", ")})`);
 74	  const body = input.body.trim();
 75	  if (!body) throw new MessageRejected("a message needs a non-empty body");
 76	  if (body.length > MAX_MESSAGE_BODY) throw new MessageRejected(`a message body is limited to ${MAX_MESSAGE_BODY} characters (got ${body.length})`);
 77	  if (UNSAFE.test(body) || UNSAFE.test(from) || UNSAFE.test(to)) throw new MessageRejected("a message may not contain control characters");
 78	  for (const ref of input.refs ?? []) {
 79	    if (!REF_KINDS.has(ref.kind)) throw new MessageRejected(`unknown reference kind '${String(ref.kind)}' (known: ${[...REF_KINDS].join(", ")})`);
 80	    if (!ref.ref) throw new MessageRejected("a message reference needs a value");
 81	    if (UNSAFE.test(ref.ref)) throw new MessageRejected("a message reference may not contain control characters");
 82	  }
 83	
 84	  const message: OperationMessage = {
 85	    id: nextId(state),
 86	    at: new Date(now).toISOString(),
 87	    from,
 88	    to,
 89	    kind: input.kind,
 90	    body,
 91	    ...(input.refs?.length ? { refs: input.refs } : {}),
 92	  };
 93	  const all = [...(state.messages ?? []), message];
 94	  const dropped: OperationMessage[] = [];
 95	  while (all.length > MAX_MESSAGES) {
 96	    // Drop a delivered message before an undelivered one: an undelivered message is still owed to a unit.
 97	    // Prefer a message no unit is owed any more; otherwise the oldest that has at least been seen once.
 98	    const index = all.findIndex((candidate) => candidate.deliveredAt !== undefined);
 99	    const [removed] = all.splice(index >= 0 ? index : 0, 1);
100	    dropped.push(removed);
101	  }
102	  state.messages = all;
103	  return { message, dropped };
104	}
105	
106	/**
107	 * Messages owed to `unitId`: addressed to it or to the operation, not from itself, not already received by it, oldest
108	 * first, bounded per turn. `to: "*"` means each unit receives it once — not that the first unit consumes it.
109	 */
110	export function undeliveredFor(state: DurableOperationState, unitId: string): OperationMessage[] {
111	  return (state.messages ?? [])
112	    .filter(
113	      (message) =>
114	        !message.deliveredTo?.includes(unitId) && message.from !== unitId && (message.to === unitId || message.to === "*"),
115	    )
116	    .slice(0, MAX_MESSAGES_PER_TURN);
117	}
118	
119	/** Records delivery. Called in the same save that starts the unit, so a crash cannot deliver twice. */
120	export function markDelivered(state: DurableOperationState, ids: string[], unitId: string, at: string): void {
121	  const wanted = new Set(ids);
122	  for (const message of state.messages ?? []) {
123	    if (!wanted.has(message.id)) continue;
124	    const to = message.deliveredTo ?? [];
125	    if (to.includes(unitId)) continue;
126	    message.deliveredTo = [...to, unitId];
127	    message.deliveredAt ??= at;
128	  }
129	}
130	
131	/**
132	 * The prompt fragment for an undelivered set. Messages are advisory context, so the heading says where they came from
133	 * and nothing more; the recipient must still read what it relies on.
134	 */
135	export function messagesBlock(messages: OperationMessage[] | undefined): string {
136	  if (!messages?.length) return "";
137	  const lines = messages.map((message) => {
138	    const refs = message.refs?.length ? ` (${message.refs.map((ref) => `${ref.kind}: ${ref.ref}`).join("; ")})` : "";
139	    return `- [${message.kind}] ${message.from}: ${message.body}${refs}`;
140	  });
141	  return `\nMessages from other units (advisory; read the referenced artifact before relying on it):\n${lines.join("\n")}\n`;
142	}
 90	export class OperationRunner {
 91	  readonly registry: ResourceRegistry;
 92	  readonly scheduler: ConvergenceScheduler;
 93	  private readonly clock: RecoveryClock;
 94	  private readonly revalidator: OperationRevalidator;
 95	  private readonly git: OperationGit | undefined;
 96	  /** One merge at a time: all units share the operation's integration worktree. */
 97	  private integrationChain: Promise<void> = Promise.resolve();
 98	
 99	  constructor(
100	    readonly state: DurableOperationState,
101	    private readonly opts: OperationRunnerOptions,
102	  ) {
103	    this.clock = opts.clock ?? realRecoveryClock;
104	    this.registry = new ResourceRegistry(state.resources, state.conditions, this.clock, (e) => this.onRegistryEvent(e));
105	    this.revalidator = new OperationRevalidator(opts.executor, this.registry, opts.onDiagnostic);
106	    this.scheduler = new ConvergenceScheduler(state, this.registry, () => this.clock.now(), opts.onEvent, opts.onDiagnostic);
107	    this.git = state.git?.isolate ? new OperationGit(planFromState(state), state.git) : undefined;
108	  }
109	
110	  async run(signal?: AbortSignal): Promise<DurableOperationState> {
111	    if (this.state.status === "COMPLETE" || this.state.status === "CANCELLED") {
112	      this.git?.disposeAllUnits();
113	      return this.state;
114	    }
115	    if (this.git) {
116	      try {
117	        ensureIntegrationWorktree(planFromState(this.state), this.state.git!, {
118	          hasHistory:
119	            (this.state.integrations?.length ?? 0) > 0 ||
120	            Object.values(this.state.git!.units).some((entry) => entry.integratedCommit !== undefined),
121	        });
122	      } catch (error: any) {
123	        this.blockOnGit(`The isolation worktree is unusable (${error?.message ?? error}).`);
124	        return this.state;
125	      }
126	      const rewound = this.git.historyProblems(this.state.integrations ?? []);
127	      if (rewound.length) {
128	        const names = rewound.map((entry) => `${entry.unitId}@${entry.integratedCommit.slice(0, 12)}`).join(", ");
129	        this.blockOnGit(`The integration branch no longer contains accepted work (${names}); it was reset or rewritten.`);
130	        return this.state;
131	      }
132	    }
133	    this.reconcileIntegrated();
134	    this.scheduler.reconcileInterruptedRuns();
135	    // Persist the interrupted-run accounting before the revalidation awaits: a crash in that window would otherwise
136	    // lose an increment and let a repeatedly interrupted unit resume without ever reaching its budget.
137	    if (this.state.units.some((unit) => unit.status === "RUNNABLE" && unit.unknownResumes > 0)) this.save();
138	    if (this.state.status === "WAITING" && this.state.wait && Date.parse(this.state.wait.wakeAt) <= this.clock.now()) {
139	      await this.revalidator.revalidate(signal);
140	    } else await this.revalidator.refresh(signal);
141	    this.save();
142	    const maxIterations = this.opts.maxIterations ?? 10_000;
143	    for (let i = 0; i < maxIterations; i++) {
144	      if (signal?.aborted) return this.cancelled();
145	      const d = this.scheduler.decide();
146	      if (d.kind === "run") {
147	        // Prepare every assignment before starting any: a unit whose isolated worktree vanished, or whose resource
148	        // needs revalidation, is handled here without leaving its batch-mates half-started.
149	        const ready: Assignment[] = [];
150	        for (const assignment of d.assignments) {
151	          const unit = assignment.unit;
152	          if (this.git) {
153	            // An authorized restart recreates the worktree; only a unit without that authorization fails closed here.
154	            const restart = Boolean(unit.pendingDecision?.restart);
155	            const missing = restart ? undefined : this.git.missingWorktrees().find((entry) => entry.unitId === unit.id);
156	            if (missing) {
157	              this.scheduler.start(assignment);
158	              this.scheduler.apply(unit.id, {
159	                kind: "failed",
160	                cause: "EXECUTION_FAILED",
161	                reason: `isolated worktree is missing (${missing.worktree})`,
162	                question: `${unit.title}'s isolated worktree was removed outside Nexus. Restart it from the integration tip, or stop?`,
163	                options: [{ label: "restart the unit from the integration tip", action: { kind: "retry", restart: true } }],
164	              });
165	              this.save();
166	              continue;
167	            }
168	          }
169	          if (await this.revalidator.beforeAssign(assignment.resource, signal)) continue;
170	          ready.push(assignment);
171	        }
172	        if (!ready.length) continue;
173	        // Delivery is recorded with the RUNNING transition: a crash either delivers with the start or not at all.
174	        const owed = new Map<string, OperationMessage[]>();
175	        const at = new Date(this.clock.now()).toISOString();
176	        for (const assignment of ready) {
177	          const messages = undeliveredFor(this.state, assignment.unit.id);
178	          if (messages.length) {
179	            owed.set(assignment.unit.id, messages);
180	            markDelivered(this.state, messages.map((message) => message.id), assignment.unit.id, at);
181	          }
182	        }
183	        for (const assignment of ready) this.scheduler.start(assignment);
184	        this.save();
185	        const results = await this.executeBatch(ready, owed, signal);
186	        for (const { assignment, result } of results) {
187	          this.scheduler.apply(assignment.unit.id, result);
188	          if (result.kind === "completed") this.publishCompletion(assignment.unit);
189	        }
190	        this.save();
191	        if (signal?.aborted) return this.cancelled();
192	        continue;
193	      }
194	      if (d.kind === "wait") {
195	        this.scheduler.wait(d);
196	        this.save();
197	        if (this.opts.maxInProcessWaitMs !== undefined && d.wakeAt - this.clock.now() > this.opts.maxInProcessWaitMs) return this.state;
198	        try {
199	          await this.clock.sleep(Math.max(0, d.wakeAt - this.clock.now()), signal);
200	        } catch {
201	          return this.cancelled();
202	        }
203	        await this.revalidator.revalidate(signal);
204	        continue;
205	      }
206	      this.scheduler.finish(d);
207	      // A blocked operation keeps its unit worktrees: the retry/restart remedies run the unit again in them.
208	      if (d.kind === "complete") {
209	      this.reportPreservedWorktrees();
