219	        unitId: "*",
220	        cause: "NOT_CONVERGING",
221	        question: `The scheduler made ${maxIterations} transitions without converging. Resume (nexus operation resume), or stop the operation?`,
222	        options: [
223	          { id: "1", label: "resume the operation", action: { kind: "keep_waiting" } },
224	          { id: "2", label: "stop the operation", action: { kind: "cancel_operation" } },
