235	   */
236	  private async executeBatch(
237	    assignments: Assignment[],
238	    owed: Map<string, OperationMessage[]>,
239	    signal?: AbortSignal,
240	  ): Promise<Array<{ assignment: Assignment; result: UnitRunResult }>> {
