242	      assignments.map(async (assignment) => ({ assignment, result: await this.execute(assignment, owed.get(assignment.unit.id), signal) })),
243	    );
244	    return settled.map((outcome, index) => {
245	      if (outcome.status === "fulfilled") return outcome.value;
246	      const reason = (outcome.reason as any)?.message ?? String(outcome.reason);
247	      return {
