 22	
 23	/** The operation document version this build writes. Independent of the task-store envelope version. */
 24	export const CURRENT_OPERATION_SCHEMA_VERSION = 2;
 25	
 26	/** The operation document version every released 1.0.0 build wrote. */
 27	export const LEGACY_OPERATION_SCHEMA_VERSION = 1;
 28	
 29	/** The largest concurrency an operation may request. A cost bound, not a capacity claim. */
 30	export const MAX_CONCURRENT_UNITS = 64;
