   134	  /**
   135	   * One driver per operation: a second process resuming it would execute its units twice. The lock names the
   136	   * holder's pid; a lock whose holder on this host is gone is stale and taken over. Returns the release function.
   137	   */
   138	  acquire(id: string): () => void {
   139	    const lockPath = path.join(this.manager.getBaseDir(), `${id}.lock`);
   140	    const create = () => fs.writeFileSync(lockPath, JSON.stringify({ pid: process.pid, host: os.hostname(), at: new Date().toISOString() }), { flag: "wx" });
   141	    try {
   142	      create();
   143	    } catch (err: any) {
   144	      if (err?.code !== "EEXIST") throw err;
   145	      let holder: { pid?: number; host?: string; at?: string } = {};
   146	      try {
   147	        holder = JSON.parse(fs.readFileSync(lockPath, "utf-8"));
   148	      } catch {
   149	        reportOperationDiagnostic(this.onDiagnostic, "persistence", "lock_read_failed");
   150	      }
   151	      // A lock written before this host last booted is stale even if its pid has since been reused.
   152	      const beforeBoot = holder.at !== undefined && Date.parse(holder.at) < Date.now() - os.uptime() * 1000;
   153	      if (holder.host !== os.hostname() || (!beforeBoot && holder.pid !== undefined && processAlive(holder.pid))) {
   154	        throw new OperationLockedError(`Operation ${id} is already being driven by pid ${holder.pid ?? "?"} on ${holder.host ?? "?"} (lock ${lockPath}).`);
   155	      }
   156	      fs.rmSync(lockPath, { force: true });
   157	      create();
   158	    }
   159	    return () => {
   160	      try {
   161	        if (JSON.parse(fs.readFileSync(lockPath, "utf-8")).pid === process.pid) fs.rmSync(lockPath, { force: true });
   162	      } catch {
   163	        reportOperationDiagnostic(this.onDiagnostic, "persistence", "lock_release_failed");
   164	      }
   165	    };
   166	  }
