260	  private async execute(d: Assignment, messages?: OperationMessage[], signal?: AbortSignal): Promise<UnitRunResult> {
261	    const { unit, resource } = d;
262	    let workspace: string | undefined;
263	    let recoverMerged = false;
264	    if (this.git) {
265	      recoverMerged = !unit.pendingDecision?.restart && this.git.canRecoverMissingWorktree(unit.id);
266	      if (!recoverMerged) {
267	        try {
268	          workspace = this.git.prepareUnit(unit, { restart: Boolean(unit.pendingDecision?.restart) }).workspace;
269	          this.save();
270	        } catch (err: any) {
271	          return {
272	            kind: "failed",
273	            cause: "EXECUTION_FAILED",
274	            reason: `cannot prepare the unit's git worktree: ${err?.message ?? err}`,
275	            question: `${unit.title}: its isolated worktree could not be prepared (${err?.message ?? err}). Retry, or stop?`,
276	            options: [{ label: "retry", action: { kind: "retry" } }],
277	          };
278	        }
279	      }
280	    }
281	    const ctx: UnitRunContext = {
282	      signal,
283	      objective: this.state.objective,
284	      dependencies: unit.dependsOn.map((id) => {
285	        const dep = this.scheduler.unit(id);
286	        return { id, title: dep.title, summary: dep.result?.summary ?? "" };
287	      }),
288	      ...(unit.agentTaskId
289	        ? {
290	            resumeReason:
291	              d.reroutedFrom?.reason ??
292	              (unit.pendingDecision ? `operator decision "${unit.pendingDecision.label}"` : undefined) ??
293	              unit.parked?.reason ??
294	              "resource became eligible again",
295	          }
296	        : {}),
297	      ...(unit.pendingDecision ? { operatorDecision: unit.pendingDecision } : {}),
298	      bindAgentTask: (taskId) => {
299	        if (unit.agentTaskId === taskId) return;
300	        unit.agentTaskId = taskId;
301	        this.save();
302	      },
303	      ...(messages?.length ? { messages } : {}),
304	      observeFailure: (f) => this.registry.observeFailure(resource, f),
305	      observeSuccess: () => this.registry.observeSuccess(resource),
306	      shouldYield: (_f, delay) => this.shouldYield(unit, resource, delay),
307	      ...(workspace ? { workspace } : {}),
