315	          question:
316	            `${unit.title}: its branch is already merged, but Nexus has no saved result to verify the task. ` +
317	            `Restart it from the merged source so it can verify the work, or stop the operation?`,
318	          options: [{ label: "restart from the merged source and verify", action: { kind: "retry", restart: true } }],
319	        };
320	      }
