 71	  /**
 72	   * Re-derives every non-terminal unit's status from dependencies and resource eligibility, then chooses the next
 73	   * transition. Called after every change (completion, resource condition, wake), never acting on stale state.
 74	   */
 75	  decide(): Decision {
 76	    const now = this.now();
 77	    if (this.state.status === "CANCELLED") return { kind: "blocked", decisions: [] };
 78	    const previous = new Map(this.state.units.map((u) => [u.id, u.status]));
 79	    // The whole selection is kept, not just the preferred resource: a unit whose preferred resource is reserved by
 80	    // an earlier assignment in the same batch may use its next qualified, eligible resource instead of waiting.
 81	    const choices = new Map<string, Selection>();
 82	    const reroutes = new Map<string, { resourceId: string; reason: string }>();
 83	
 84	    for (const u of this.state.units) {
 85	      if (TERMINAL.includes(u.status) || u.status === "RUNNING") continue;
 86	      const deps = u.dependsOn.map((d) => this.unit(d));
 87	      if (deps.some((d) => d.status !== "COMPLETE")) {
 88	        u.status = "WAITING_ON_DEPENDENCY";
 89	        delete u.parked;
 90	        continue;
 91	      }
 92	      const sel = u.override ? this.overrideSelection(u, now) : this.registry.select(u.requires, this.excludedModels(u), now);
 93	      if (sel.chosen) {
 94	        u.status = "RUNNABLE";
 95	        const from = u.assignment?.resourceId;
 96	        let reroutedFrom: { resourceId: string; reason: string } | undefined;
 97	        if (from && from !== sel.chosen.id) {
 98	          const prior = this.registry.get(from);
 99	          const elig = prior ? this.registry.eligibility(prior, now) : undefined;
100	          const reason = !prior
101	            ? "previous resource is no longer configured"
102	            : u.override?.resourceId === sel.chosen.id
103	              ? `operator assigned ${sel.chosen.id}`
104	              : elig && !elig.eligible
105	                ? elig.blocking.map((b) => b.reason).join("; ")
106	                : `${sel.chosen.id} is the preferred qualified resource`;
107	          reroutedFrom = { resourceId: from, reason };
108	        }
109	        choices.set(u.id, sel);
110	        if (reroutedFrom) reroutes.set(u.id, reroutedFrom);
111	        continue;
112	      }
113	      const temporary = sel.qualified.filter((c) => !c.eligibility.permanent && c.eligibility.eligibleAt !== undefined);
114	      if (temporary.length) {
115	        const wakeAt = Math.min(...temporary.map((c) => c.eligibility.eligibleAt!));
116	        const reason = temporary
117	          .map((c) => `${c.resource.id} ${c.eligibility.blocking.map((b) => b.reason).join(", ")}`)
118	          .join("; ");
119	        const wasParked = u.status === "PARKED";
120	        u.status = "PARKED";
121	        u.parked = {
122	          since: wasParked && u.parked ? u.parked.since : new Date(now).toISOString(),
123	          reason,
124	          resourceIds: temporary.map((c) => c.resource.id),
125	          wakeAt: new Date(wakeAt).toISOString(),
126	        };
127	        continue;
128	      }
129	      this.block(u, this.noQualifiedResource(u, sel));
130	    }
131	
132	    for (const u of this.state.units) {
133	      const before = previous.get(u.id);
134	      if (u.status === "PARKED" && before !== "PARKED") {
135	        const others = this.productiveOthers(u.id, choices);
136	        this.emit(
137	          "WORK_PARKED",
138	          `${u.title} parked: ${u.parked!.reason}; eligible again ${clockTime(Date.parse(u.parked!.wakeAt!))}.` +
139	            (others ? ` Continuing ${others} independent ${others === 1 ? "task" : "tasks"}.` : ""),
140	          { unitId: u.id, detail: { parked: u.parked } },
141	        );
142	      }
143	    }
144	
145	    // Required work first; advisory work runs when it can but never ahead of the objective.
146	    const runnable = this.state.units.filter((u) => u.status === "RUNNABLE" && choices.has(u.id));
147	    const ordered = this.orderRunnable(runnable);
148	    const assignments = this.assign(ordered, choices, reroutes);
149	    if (assignments.length) {
150	      const limit = effectiveConcurrency(this.state);
151	      const running = this.state.units.filter((u) => u.status === "RUNNING").length;
152	      if (ordered.length > assignments.length && running + assignments.length >= limit) {
153	        // One notice per distinct truncation, not one per decide() call: the scheduler is called repeatedly over the
154	        // same state and the event ring holds 300 entries for the whole operation.
155	        const signature = `${limit}|${running}|${ordered.map((u) => u.id).join(",")}`;
156	        if (this.concurrencyNotice !== signature) {
157	          this.concurrencyNotice = signature;
158	          this.emit(
159	            "CONCURRENCY_LIMIT",
160	            `${ordered.length} units are runnable; starting ${assignments.length} (limit ${limit}).`,
161	            { detail: { limit, eligible: ordered.length } },
162	          );
163	        }
164	      }
165	      return { kind: "run", assignments };
166	    }
167	
168	    // Every runnable unit's qualified slots are held by work already in flight: nothing can start now, and the batch
169	    // that holds them will re-enter decide() when it settles. This is not a block and not a wait on a resource window.
170	    if (assignments.length === 0 && this.state.units.some((u) => u.status === "RUNNING")) {
171	      return {
172	        kind: "wait",
173	        wakeAt: now + this.state.policy.minWaitMs,
174	        reason: "every runnable unit's qualified resource is busy",
175	        parked: [],
175	      return { condition: "TEMPORARILY_UNAVAILABLE", scope: "model", temporary: true };
176	    case "REQUEST_REJECTED":
177	      if (code === "capability_unsupported") return { condition: "DEGRADED", scope: "model", temporary: true };
178	      if (failure.httpStatus === 404 || code === "model_not_found") return { condition: "PERMANENTLY_UNAVAILABLE", scope: "model", temporary: false };
