180	    case "PERMANENT_FAILURE":
181	      // TLS/DNS failures: the endpoint cannot be used without operator action.
182	      if (failure.kind === "network_error") return { condition: "PERMANENTLY_UNAVAILABLE", scope: "endpoint", temporary: false };
183	      return null;
184	    default:
185	      return null;
186	  }
