219	  /** Records the condition a failure evidences for `resource`; returns it, or null if the failure is request-scoped. */
220	  observeFailure(resource: ResourceDescriptor, failure: InferenceFailure): ResourceConditionRecord | null {
221	    const derived = conditionFromFailure(resource, failure);
