223	    const key = scopeKey(resource, derived.scope);
224	    if (!key) return null;
225	    const now = this.clock.now();
226	    // Expired windows still count: only a success resets the backoff for a scope.
227	    const prior = this.conditions.find((c) => c.key === key);
228	    const failures = (prior?.failures ?? 0) + 1;
229	    const hints = failure.hints ?? {};
