231	      scope: derived.scope,
232	      key,
233	      condition: derived.condition,
234	      temporary: derived.temporary,
235	      source: "backoff",
236	      confidence: "derived",
237	      reason: `${derived.condition.toLowerCase().replace(/_/g, " ")}${failure.httpStatus ? ` (HTTP ${failure.httpStatus})` : ` (${failure.kind})`}`,
238	      observedAt: new Date(now).toISOString(),
239	      failures,
240	      resourceId: resource.id,
241	      ...(failure.requestId ? { requestId: failure.requestId } : {}),
