106	/**
107	 * Messages owed to `unitId`: addressed to it or to the operation, not from itself, not already received by it, oldest
108	 * first, bounded per turn. `to: "*"` means each unit receives it once — not that the first unit consumes it.
109	 */
110	export function undeliveredFor(state: DurableOperationState, unitId: string): OperationMessage[] {
111	  return (state.messages ?? [])
112	    .filter(
113	      (message) =>
114	        !message.deliveredTo?.includes(unitId) && message.from !== unitId && (message.to === unitId || message.to === "*"),
115	    )
116	    .slice(0, MAX_MESSAGES_PER_TURN);
117	}
