119	/** Records delivery. Called in the same save that starts the unit, so a crash cannot deliver twice. */
120	export function markDelivered(state: DurableOperationState, ids: string[], unitId: string, at: string): void {
121	  const wanted = new Set(ids);
122	  for (const message of state.messages ?? []) {
123	    if (!wanted.has(message.id)) continue;
124	    const to = message.deliveredTo ?? [];
125	    if (to.includes(unitId)) continue;
126	    message.deliveredTo = [...to, unitId];
127	    message.deliveredAt ??= at;
128	  }
129	}
