export function applyOperatorDecision(
  store: OperationStore,
  id: string,
  decisionId: string,
  optionId: string,
  note?: string,
  opts: { now?: () => number; onEvent?: (e: OperationEvent) => void; onDiagnostic?: OperationDiagnosticHandler } = {},
