  confirm?: boolean;
  // Override the POST URL. Default https://xerj.org/api/field-report, or XERJ_FIELD_REPORT_URL when that is set. Must be http or https.
  endpoint?: string;
  // Try the GitHub PR first. Default true. false skips GitHub and POSTs straight to the endpoint.
  github?: boolean;
  // What was indexed. Optional.
  indexed?: string;
  // The full report. Optional, capped at 4000 characters.
  notes?: string;
  // OS and architecture. Optional: when omitted, this machine's OS and architecture are sent.
  os?: string;
  // What XERJ was used for, in one sentence.
  used_for: string;
  // What worked and what did not, in one or two sentences (up to 1000 characters). Put the long report in notes.
