  if (task.repo) {
    need(typeof task.repo.url === "string" && task.repo.url.length > 0, "repo.url is required");
    try {
      const repoUrl = new URL(task.repo.url);
      need(repoUrl.protocol === "https:" && !repoUrl.username && !repoUrl.password, "repo.url must use HTTPS without embedded credentials");
    } catch { need(false, "repo.url must be a valid HTTPS URL without embedded credentials"); }
    need(/^[0-9a-f]{40}$/.test(task.repo.commit ?? ""), "repo.commit must be a full 40-character commit id (pinned)");
  }
  const hiddenCommand = typeof task.hidden?.command === "string" && task.hidden.command.length > 0;
  const hiddenOracle = task.hidden?.protocol === "blackbox-v1";
  need(hiddenCommand || hiddenOracle, "hidden.command or hidden blackbox-v1 oracle is required");
  if (hiddenOracle) {
    const oracleProblem = blackBoxOracleProblem(task.hidden, dir, task.fixture ?? null);
    need(!oracleProblem, oracleProblem ?? "hidden black-box oracle is invalid");
  }
  // Legacy validators execute candidate modules in the same runtime. File hiding and a fresh workspace cannot prevent
  // candidate code from inspecting or mutating that runtime, so they are never valid independent qualification.
  if (qualification) need(hiddenOracle && !hiddenCommand, "qualification requires the isolated blackbox-v1 hidden oracle; in-process legacy validators are not accepted");
  if (task.hidden?.dir) {
    try { confinedPath(dir, task.hidden.dir); }
    catch (error) { need(false, error.message); }
  }
  if (task.regression?.dir) {
    try { confinedPath(dir, task.regression.dir); }
    catch (error) { need(false, error.message); }
  }
  for (const key of ["steps", "minutes"]) {
    if (task[key] !== undefined) need(Number.isInteger(task[key]) && task[key] > 0, `${key} must be a positive integer`);
  }
  if (task.faults !== undefined) {
    const kinds = ["refuse", "overloaded", "stream_cut", "truncate", "context_overflow", "malformed_tool_json"];
    need(Array.isArray(task.faults) && task.faults.every((f) => kinds.includes(f?.kind) && Number.isInteger(f?.atRequest) && f.atRequest >= 1), `faults must be [{ kind: ${kinds.join("|")}, atRequest: n >= 1 }]`);
  }
  if (task.t4RunnerFault !== undefined) {
    need(task.tier === "T4" && task.t4RunnerFault === "sigterm_resume", "t4RunnerFault is supported only as sigterm_resume on a T4 task");
  }
  problems.push(...t4FixtureProblems(task));
  if (task.class !== undefined || qualification) need(CLASSES.includes(task.class), `class must be one of ${CLASSES.join(", ")}`);
  if (task.difficulty !== undefined || qualification) need(DIFFICULTIES.includes(task.difficulty), `difficulty must be one of ${DIFFICULTIES.join(", ")}`);
  return problems;
}

/**
 * What a run's model is, beyond its alias: from the endpoint's /models entry (id, owner, advertised context) and the
function expandHome(f) {
  return f.replace(/^~(?=\/)/, os.homedir());
}

function sh(command, argv, cwd, allowFailure = false) {
  const r = spawnSync(command, argv, {
    cwd,
    encoding: "utf8",
    timeout: 120_000,
    env: { PATH: "/usr/bin:/bin", HOME: os.tmpdir(), GIT_CONFIG_NOSYSTEM: "1", GIT_CONFIG_GLOBAL: "/dev/null", GIT_TERMINAL_PROMPT: "0", GIT_ALLOW_PROTOCOL: "https" },
  });
  if (r.status !== 0 && !allowFailure) throw new Error(`${path.basename(command)} failed (${r.status ?? "signal"}): ${(r.stderr || r.stdout || "").slice(-2000)}`);
  return r.status;
}

function parseArgs(list) {
  const out = {};
  for (let i = 0; i < list.length; i++) {
    const key = list[i].replace(/^--/, "");
    const next = list[i + 1];
    if (next === undefined || next.startsWith("--")) out[key] = true;
    else {
      out[key] = next;
      i++;
    }
  }
  return out;
}
// Stages a pinned repository commit as a candidate workspace that carries no history beyond that commit.
// Held-out baselines are the parent of an upstream fix, so any descendant object, ref, remote or alternates link in
// the workspace would expose the reference solution to the candidate (eval/README.md, "Hidden tests").
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

/**
 * `cache` is a trusted local clone that may hold upstream history after `commit`. The workspace is a fresh repository
 * that fetches only `commit` and its ancestors: no `--shared`, no alternates, no remote, no tags, no FETCH_HEAD.
 */
export function stageRepoWorkspace(cache, commit, ws) {
  if (!/^[0-9a-f]{40}$/.test(commit)) throw new Error("repository workspace requires a full pinned commit");
  const source = fs.realpathSync(cache);
  git(["-c", "init.defaultBranch=main", "init", "-q", ws], os.tmpdir());
  git(["fetch", "-q", "--no-tags", "--no-write-fetch-head", source, commit], ws, "file");
  git(["checkout", "-q", "--detach", commit], ws);
  const problem = workspaceHistoryProblem(ws, commit);
  if (problem) throw new Error(`staged workspace is not history-isolated: ${problem}`);
}

/** Null when `ws` exposes nothing beyond `commit` and its ancestors; otherwise the first exposure found. */
export function workspaceHistoryProblem(ws, commit) {
  const gitDir = path.join(ws, ".git");
  if (fs.existsSync(path.join(gitDir, "objects", "info", "alternates"))) return "objects/info/alternates is present";
  if (fs.existsSync(path.join(gitDir, "FETCH_HEAD"))) return "FETCH_HEAD is present";
  if (git(["remote"], ws).trim()) return "a remote is configured";
  const head = git(["rev-parse", "HEAD"], ws).trim();
  if (head !== commit) return `HEAD is ${head}, not the pinned commit`;
  const beyond = git(["rev-list", "--all", "--reflog", `^${commit}`], ws).trim();
  if (beyond) return `${beyond.split("\n").length} commit(s) reachable that are not ancestors of the pinned commit`;
  const reachable = new Set(git(["rev-list", "--objects", commit], ws).split("\n").map((line) => line.split(" ", 1)[0]).filter(Boolean));
  const objects = git(["cat-file", "--batch-check=%(objectname)", "--batch-all-objects"], ws).split("\n").map((line) => line.trim()).filter(Boolean);
  const unreachable = objects.filter((object) => !reachable.has(object));
  if (unreachable.length) return `${unreachable.length} unreachable object(s) in .git/objects: ${unreachable.slice(0, 5).join(", ")}`;
  return null;
}

function git(argv, cwd, allowProtocol = "none") {
  const result = spawnSync("git", argv, {
    cwd,
    encoding: "utf8",
    timeout: 120_000,
    env: { PATH: "/usr/bin:/bin", HOME: os.tmpdir(), GIT_CONFIG_NOSYSTEM: "1", GIT_CONFIG_GLOBAL: "/dev/null", GIT_TERMINAL_PROMPT: "0", GIT_ALLOW_PROTOCOL: allowProtocol },
  });
  if (result.status !== 0) throw new Error(`git ${argv[0] === "-c" ? argv[2] : argv[0]} failed (${result.status ?? "signal"}): ${(result.stderr || result.stdout || "").slice(-2000)}`);
  return result.stdout;
}
/**
 * The evaluation harness end to end against a scripted model (Stage 8, T1 smoke): fresh workspaces, hidden tests the
 * agent never sees, separate scores. The self-test task is the assessment's A1 case: a repository whose own suite is
 * green but never exercises the deliverable. A wrong deliverable must fail the hidden test and must never be VERIFIED.
 */

import { test } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawn, spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { startGateway, Reply } from "./helpers/fixtures.js";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");

async function sealTestTasks(tasksDir: string, taskId: string) {
  const { corpusTaskRows } = await import(path.join(ROOT, "eval/validate.mjs"));
  const rows = corpusTaskRows(tasksDir, [taskId]);
  const manifestPath = path.join(tasksDir, "custody-manifest.json");
  const manifest = { schemaVersion: 1, split: "heldout", custody: { status: "approved", custodian: "synthetic-test-role", approvedAt: "2026-01-01T00:00:00Z" }, tasks: rows };
  const bytes = JSON.stringify(manifest);
  fs.writeFileSync(manifestPath, bytes);
  return { corpusManifest: manifestPath, corpusManifestSha256: createHash("sha256").update(bytes).digest("hex") };
}

/** Async: the scripted gateway answers from this process, so the runner must not block its event loop. */
function runNode(argv: string[], env: NodeJS.ProcessEnv = process.env): Promise<{ status: number | null; stdout: string; stderr: string }> {
  return new Promise((resolve) => {
    const child = spawn(process.execPath, argv, { stdio: ["ignore", "pipe", "pipe"], env });
    let stdout = "";
    let stderr = "";
    child.stdout.on("data", (c) => (stdout += c));
    child.stderr.on("data", (c) => (stderr += c));
    child.on("close", (status) => resolve({ status, stdout, stderr }));
  });
}

function writer(content: string) {
  return (_n: number, body: any): Reply => {
    const tools = (body?.messages ?? []).filter((m: any) => m.role === "tool").length;
    if (tools === 0) return { kind: "tools", calls: [{ name: "write_file", args: { path: "math.js", content } }] };
    if (tools === 1) return { kind: "tools", calls: [{ name: "task_completed", args: { summary: "math.js added" } }] };
    return { kind: "text", content: "Done." };
  };
}

async function evaluate(content: string, extra: Record<string, unknown> = {}): Promise<{ records: any[]; score: any; hiddenLog: string; agentLog: string; agentError: string }> {
  const gw = await startGateway(writer(content));
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-eval-out-"));
  const out = path.join(root, "run");
  const config = path.join(root, "config.json");
  fs.writeFileSync(config, JSON.stringify({ name: "nexus@mock", agent: "nexus", endpoint: gw.url, model: "m", runs: 1, steps: 20, minutes: 5, ...extra }));
  try {
    const run = await runNode([path.join(ROOT, "eval/run.mjs"), "--config", config, "--out", out, "--only", "selftest-add"]);
    assert.equal(run.status, 0, `${run.stdout}\n${run.stderr}`);
    const records = fs.readFileSync(path.join(out, "results.jsonl"), "utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l));
    const scored = spawnSync(process.execPath, [path.join(ROOT, "eval/score.mjs"), path.join(out, "results.jsonl"), "--json"], { encoding: "utf8" });
    assert.equal(scored.status, 0, scored.stderr);
    const manifest = JSON.parse(fs.readFileSync(path.join(out, "manifest.json"), "utf8"));
    assert.deepEqual(manifest.tasks.map((task: any) => task.id), ["selftest-add"]);
    assert.match(manifest.harness.sourceSha256, /^[0-9a-f]{64}$/);
    assert.match(manifest.configSha256, /^[0-9a-f]{64}$/);
    const priorResults = fs.readFileSync(path.join(out, "results.jsonl"), "utf8");
    const replay = await runNode([path.join(ROOT, "eval/run.mjs"), "--config", config, "--out", out, "--only", "selftest-add"]);
    assert.equal(replay.status, 2);
    assert.match(replay.stderr, /output directory must be new/);
    assert.equal(fs.readFileSync(path.join(out, "results.jsonl"), "utf8"), priorResults, "reusing an output directory changed prior evidence");
    assert.match(manifest.harness.string, /^[0-9a-f]{12}/);
    const logDir = records[0].logs ? path.join(out, records[0].logs) : null;
    const readLog = (file: string) => logDir && fs.existsSync(path.join(logDir, file)) ? fs.readFileSync(path.join(logDir, file), "utf8") : "<not written>";
    return { records, score: JSON.parse(scored.stdout), hiddenLog: readLog("hidden.log"), agentLog: readLog("agent.stdout.json"), agentError: readLog("agent.stderr.log") };
  } finally {
    await gw.close();
    fs.rmSync(root, { recursive: true, force: true });
  }
}

test("a correct deliverable passes the hidden test; a wrong one fails it and is never VERIFIED (A1)", { timeout: 300_000 }, async () => {
  const good = await evaluate("exports.add = (a, b) => a + b;\n");
  assert.equal(good.records.length, 1);
  assert.equal(good.records[0].hiddenPass, true, `${JSON.stringify(good.records[0])}\nagent=${good.agentLog}\nagent-error=${good.agentError}\nhidden=${good.hiddenLog}`);
  assert.equal(good.records[0].regressionPass, true);
  assert.equal(good.records[0].falseVerified, false);

  const wrong = await evaluate("exports.add = (a, b) => a - b;\n");
  const r = wrong.records[0];
  assert.equal(r.hiddenPass, false, "the hidden test catches the wrong deliverable");
  assert.equal(r.regressionPass, true, "the repository's own suite is still green");
  assert.notEqual(r.turn?.outcome, "VERIFIED", `an unrelated green suite does not verify it: ${JSON.stringify(r.turn)}`);
  assert.equal(r.falseVerified, false);
  assert.equal(wrong.score.totals.falseVerified, 0);
  assert.equal(wrong.score.rows[0].correct, 0);
});

