  Module._extensions[extension] = function loadOracleOrModule(module, filename) {
    const absolute = path.resolve(filename);
    if (!saved.has(absolute)) {
      if (absolute.startsWith("/workspace/")) {
        saved.clear();
        restoreExtensions();
      }
      return load(module, filename);
    }
