const MAX_TASK_FILE_BYTES = 64 * 1024 * 1024;
const MAX_TASK_TREE_BYTES = 512 * 1024 * 1024;
const MAX_TASK_TREE_ENTRIES = 50_000;
const MAX_TASK_TREE_DEPTH = 64;
