--- /dev/null
+++ b/cli/test/index_error_redaction.test.ts
@@ -0,0 +1,50 @@
+import { test } from "node:test";
+import assert from "node:assert/strict";
+import { InformationFlowBoundary } from "../src/core/egress.js";
+import { redactDiagnosticForOutput } from "../src/core/persistence_protection.js";
+import { safeTerminal } from "../src/ui.js";
+
+test("redacts diagnostic text used by JSON task failure output", () => {
+  const original = InformationFlowBoundary.getGlobalInstance();
+  const secret = "synthetic_json_error_secret_22b1";
+  InformationFlowBoundary.setGlobalInstance(new InformationFlowBoundary({ explicitSecrets: [secret] }));
+  try {
+    const safePrompt = redactDiagnosticForOutput(`user task includes ${secret}`);
+    const safeError = redactDiagnosticForOutput(`failed with ${secret}`);
+    assert.equal(safePrompt.includes(secret), false);
+    assert.equal(safeError.includes(secret), false);
+    assert.match(safePrompt, /REDACTED/);
+    assert.match(safeError, /REDACTED/);
+  } finally {
+    InformationFlowBoundary.setGlobalInstance(original);
+  }
+});
+
+test("suppresses JSON diagnostic text if canonical classification fails", () => {
+  const original = InformationFlowBoundary.getGlobalInstance();
+  const boundary = new InformationFlowBoundary();
+  boundary.classifyText = () => { throw new Error("synthetic classifier failure"); };
+  InformationFlowBoundary.setGlobalInstance(boundary);
+  try {
+    const unsafe = "synthetic_json_error_secret_22b1";
+    const responseText = redactDiagnosticForOutput(`prompt/error: ${unsafe}`);
+    assert.match(responseText, /diagnostic suppressed/);
+    assert.equal(responseText.includes(unsafe), false);
+  } finally {
+    InformationFlowBoundary.setGlobalInstance(original);
+  }
+});
+
+test("redacts credentials and terminal controls from CLI error output", () => {
+  const original = InformationFlowBoundary.getGlobalInstance();
+  const secret = "synthetic_cli_output_secret_41a9";
+  InformationFlowBoundary.setGlobalInstance(new InformationFlowBoundary({ explicitSecrets: [secret] }));
+  try {
+    const formatted = safeTerminal(redactDiagnosticForOutput(`failed with ${secret}\u001b[31m`));
+    assert.equal(formatted.includes(secret), false);
+    assert.equal(formatted.includes("\u001b"), false);
+    assert.match(formatted, /REDACTED/);
+  } finally {
+    InformationFlowBoundary.setGlobalInstance(original);
+  }
+});
diff --git a/cli/test/middleware_audit_redaction.test.ts b/cli/test/middleware_audit_redaction.test.ts
new file mode 100644
index 00000000..cecf2cc9
--- /dev/null
+++ b/cli/test/middleware_audit_redaction.test.ts
@@ -0,0 +1,76 @@
+import { after, test } from "node:test";
+import assert from "node:assert/strict";
+import * as fs from "node:fs";
+import * as os from "node:os";
+import * as path from "node:path";
+import { InformationFlowBoundary } from "../src/core/egress.js";
+import { recordMiddlewareAudit } from "../src/core/persistence_protection.js";
+
+const originalBoundary = InformationFlowBoundary.getGlobalInstance();
+const temporaryHomes: string[] = [];
+
+function setIsolatedHome(): string {
+  const home = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-middleware-audit-redaction-"));
+  temporaryHomes.push(home);
+  process.env.HOME = home;
+  return home;
+}
+
+after(() => {
+  InformationFlowBoundary.setGlobalInstance(originalBoundary);
+  for (const home of temporaryHomes) fs.rmSync(home, { recursive: true, force: true });
+});
+test("redacts synthetic credentials from middleware audit metadata before the disk append", () => {
+  const previousHome = process.env.HOME;
+  const home = setIsolatedHome();
+  const secret = "synthetic_middleware_credential_73ac";
+  InformationFlowBoundary.setGlobalInstance(new InformationFlowBoundary({ explicitSecrets: [secret] }));
+
+  try {
+    recordMiddlewareAudit({
+      kind: "middleware_rewrite",
+      plugin: `plugin-${secret}`,
+      tool: "write_file",
+      phase: "pre",
+      before_digest: "safe-before-digest",
+      after_digest: "safe-after-digest",
+      workspace: `/tmp/workspace-${secret}`,
+    });
+
+    const auditPath = path.join(home, ".nexus", "audit.log");
+    const contents = fs.readFileSync(auditPath, "utf8");
+    assert.equal(contents.includes(secret), false);
+    assert.match(contents, /REDACTED/);
+    assert.match(contents, /safe-before-digest/);
+    assert.match(contents, /safe-after-digest/);
+    assert.equal(JSON.parse(contents).kind, "middleware_rewrite");
+  } finally {
+    if (previousHome === undefined) delete process.env.HOME;
+    else process.env.HOME = previousHome;
+    InformationFlowBoundary.setGlobalInstance(originalBoundary);
+  }
+});
+
+test("skips middleware audit persistence when telemetry classification fails", () => {
+  const previousHome = process.env.HOME;
+  const home = setIsolatedHome();
+  const boundary = new InformationFlowBoundary();
+  boundary.classifyText = () => { throw new Error("synthetic classifier failure"); };
+  InformationFlowBoundary.setGlobalInstance(boundary);
+
+  try {
+    recordMiddlewareAudit({
+      kind: "middleware_rewrite",
+      plugin: "synthetic-plugin",
+      tool: "write_file",
+      phase: "post",
+      before_digest: "safe-before",
+      after_digest: "safe-after",
+    });
+    assert.equal(fs.existsSync(path.join(home, ".nexus", "audit.log")), false);
+  } finally {
+    if (previousHome === undefined) delete process.env.HOME;
+    else process.env.HOME = previousHome;
+    InformationFlowBoundary.setGlobalInstance(originalBoundary);
+  }
+});
