+    assert.equal(formatProviderDiagnostic("Provider request failed"), "Provider request failed");
+
+    boundary.redactForTelemetry = () => {
+      throw new Error(syntheticCredential);
+    };
+    assert.equal(formatProviderDiagnostic(`Provider request failed: ${syntheticCredential}`), "[diagnostic suppressed: credential sanitization failed]");
+  } finally {
+    InformationFlowBoundary.setGlobalInstance(original);
+  }
